#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;
using u128 = __uint128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull n, m, k;
    cin >> n >> m >> k;

    auto enough = [&](ull x) {
        ull limit = min(n, x);
        ull full = min(limit, x / m);
        u128 count = static_cast<u128>(full) * m;

        ull i = full + 1;
        while (i <= limit && count < k) {
            ull q = x / i;
            ull last = min(limit, x / q);
            count += static_cast<u128>(q) * (last - i + 1);
            i = last + 1;
        }

        return count >= k;
    };

    ull low = 1, high = k;
    while (low < high) {
        ull mid = low + (high - low) / 2;
        if (enough(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low;
    return 0;
}

